<?php
declare(strict_types=1);
require_once __DIR__.'/includes/init.php';
require_once __DIR__.'/csrf_helper.php';
require_once __DIR__.'/includes/club_rewards.php';
if(empty($_SESSION['trener_id'])){header('Location: login.php');exit;}
$actor=(int)$_SESSION['trener_id'];
try{clubRewardActor($pdo,$actor,['coach','sports_lead','finance_manager']);}catch(Throwable){http_response_code(403);exit('Výkazy a odměny nejsou dostupné ve vaší pracovní pozici.');}
$position=staffActivePosition();$ready=accountingLedgerTable($pdo,'club_reward_claims');$error='';$success='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 if(!csrf_verify((string)($_POST['csrf_token']??''))){http_response_code(403);$error='Formulář vypršel. Obnovte stránku.';}
 else try {
  if(!$ready)throw new DomainException('Evidence odměn ještě není připravena.');$reason=(string)($_POST['reason']??'');$confirmed=($_POST['confirmed']??'')==='1';$action=$_POST['action']??'';
  if($action==='rule'){clubRewardRule($pdo,['kind'=>$_POST['kind']??'','unit'=>$_POST['unit']??'','rate_minor'=>clubRewardAmount((string)($_POST['rate']??'')),'valid_from'=>$_POST['valid_from']??'','valid_to'=>$_POST['valid_to']??'','title'=>$_POST['title']??'','approval_evidence'=>$_POST['approval_evidence']??'','accounting_method'=>$_POST['accounting_method']??''],$actor,$reason,$confirmed);$success='Výslovně doložené pravidlo bylo uloženo jako neměnná verze.';}
  elseif($action==='submit'){
   $input=$_POST;foreach(['subject'=>['kind',['coach','athlete']],'recipient'=>['recipient_kind',['trainer','person']]] as $prefix=>[$kindField,$kinds])if(isset($input[$prefix.'_ref'])){[$kind,$id]=array_pad(explode(':',(string)$input[$prefix.'_ref'],2),2,'');if(!in_array($kind,$kinds,true)||!ctype_digit($id))throw new DomainException('Vyberte konkrétní osobu z nabídky.');$input[$kindField]=$kind;$input[$prefix.'_id']=(int)$id;}
   clubRewardSubmit($pdo,$input,$actor,$reason,$confirmed);$success='Výkaz byl předložen v nové neměnné verzi. Vyžaduje samostatné schválení.';}
  elseif($action==='decide'){clubRewardDecide($pdo,(int)($_POST['version_id']??0),(string)($_POST['outcome']??''),$actor,$reason,$confirmed);$success='Rozhodnutí bylo zaznamenáno. Schválení není výplata.';}
  elseif($action==='pay'){clubRewardPay($pdo,(int)($_POST['claim_id']??0),['movement_id'=>(int)($_POST['movement_id']??0),'amount_minor'=>clubRewardAmount((string)($_POST['amount']??'')),'received_by'=>$_POST['received_by']??'','request_key'=>$_POST['request_key']??'','paid_on'=>$_POST['paid_on']??''],$actor,$reason,$confirmed);$success='Doložený pohyb byl přiřazen k odměně. Žádný příkaz bance nebyl odeslán.';}
  else throw new DomainException('Neznámý úkon.');
 }catch(DomainException|InvalidArgumentException|AccountingLedgerException $e){http_response_code(422);$error=$e->getMessage();}catch(Throwable $e){error_log('club_rewards: '.$e->getMessage());http_response_code(422);$error='Úkon se nepodařil. Žádná částečná změna nebyla potvrzena.';}
}
function rewardH(mixed $s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function rewardMoney(int $minor):string{return number_format($minor/100,2,',',' ').' Kč';}
function rewardFields():void{echo csrf_field().'<input type="hidden" name="request_key" value="'.bin2hex(random_bytes(16)).'">';}
function rewardConfirm():void{echo '<label class="d-block my-2">Důvod a podklad úkonu<input class="form-control" name="reason" minlength="10" maxlength="1000" required></label><label class="d-block my-2"><input type="checkbox" name="confirmed" value="1" required> Potvrzuji skutečné podklady a správnost úkonu</label>';}
$rules=$ready?$pdo->query('SELECT * FROM club_reward_rules ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC):[];
$people=$pdo->query('SELECT id,jmeno,prijmeni FROM sportovci ORDER BY prijmeni,jmeno')->fetchAll(PDO::FETCH_ASSOC);
$trainers=$pdo->query("SELECT id,jmeno,'' AS prijmeni FROM treneri ORDER BY jmeno")->fetchAll(PDO::FETCH_ASSOC);
if($position==='coach'){$people=[];$trainers=array_values(array_filter($trainers,static fn($r)=>(int)$r['id']===$actor));}
$claims=[];if($ready){$q=$pdo->prepare('SELECT * FROM club_reward_claims'.($position==='coach'?" WHERE kind='coach' AND subject_id=?":'').' ORDER BY id DESC LIMIT 100');$q->execute($position==='coach'?[$actor]:[]);$claims=$q->fetchAll(PDO::FETCH_ASSOC);}
$movements=$ready&&$position==='finance_manager'?$pdo->query("SELECT id,effective_on,amount_minor,source_reference FROM accounting_movements WHERE kind IN ('expense','income','reversal') ORDER BY id DESC LIMIT 200")->fetchAll(PDO::FETCH_ASSOC):[];
function rewardSubmitForm(array $rules,array $trainers,array $people,?array $claim=null,?array $version=null):void {
 $source=$claim??[];$v=$version??[];rewardFields();echo '<input type="hidden" name="action" value="submit"><input type="hidden" name="claim_id" value="'.(int)($source['id']??0).'"><input type="hidden" name="expected_version" value="'.(int)($v['version']??0).'">';
 if($claim){foreach(['kind','subject_id','date_from','date_to'] as $k)echo '<input type="hidden" name="'.$k.'" value="'.rewardH($source[$k]).'">';}
 else {echo '<label class="d-block">Osoba a druh výkazu<select class="form-select" name="subject_ref" required><option value="">Vyberte osobu</option>';foreach(['Trenér'=>$trainers,'Sportovec'=>$people] as $label=>$rows)foreach($rows as $r)echo '<option value="'.($label==='Trenér'?'coach':'athlete').':'.(int)$r['id'].'">'.rewardH($label.' #'.$r['id'].' '.$r['prijmeni'].' '.$r['jmeno']).'</option>';echo '</select></label><div class="row"><label class="col">Od<input class="form-control" type="date" name="date_from" required></label><label class="col">Do<input class="form-control" type="date" name="date_to" required></label></div>';}
 echo '<label class="d-block">Schválené pravidlo<select class="form-select" name="rule_id" required><option value="">Vyberte platné pravidlo</option>';foreach($rules as $r)echo '<option value="'.(int)$r['id'].'" '.((int)($v['rule_id']??0)===(int)$r['id']?'selected':'').'>'.rewardH($r['title'].' · '.$r['valid_from'].' – '.$r['valid_to'].' · '.rewardMoney((int)$r['rate_minor']).'/'.($r['unit']==='hour'?'hod':'trénink')).'</option>';echo '</select></label>';
 echo '<label class="d-block">Konkrétní příjemce<select class="form-select" name="recipient_ref" required><option value="">Vyberte příjemce</option>';foreach(['Pracovník'=>$trainers,'Osoba'=>$people] as $label=>$rows)foreach($rows as $r){$kind=$label==='Pracovník'?'trainer':'person';echo '<option value="'.$kind.':'.(int)$r['id'].'" '.((int)($v['recipient_id']??0)===(int)$r['id']&&($v['recipient_kind']??'')===$kind?'selected':'').'>'.rewardH($label.' #'.$r['id'].' '.$r['prijmeni'].' '.$r['jmeno']).'</option>';}echo '</select></label><label class="d-block">Oprávnění příjemce, dohoda a podklad (u dítěte též způsob převzetí)<input class="form-control" name="recipient_evidence" maxlength="2000" value="'.rewardH($v['recipient_evidence']??'').'" required></label>';rewardConfirm();echo '<button class="btn btn-primary">Předložit '.($claim?'opravnou verzi':'výkaz').'</button>';
}
?>
<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Výkazy a odměny</title><?php require_once __DIR__.'/includes/ui_shell.php';appUiAssets();?></head><body><?php require __DIR__.'/hlavicka.php';?><main class="container py-4"><h1>Výkazy a odměny</h1><p>Skutečná činnost → předložená verze → schválení jiným vedoucím → doložená výplata. Pravidla se zadávají podle rozhodnutí vedení a účetní; systém nepočítá mzdy ani odvody.</p>
<p><a href="vypis_vykazu.php">Původní přehled činností</a> · <a href="sports_activity_admin.php">Sportovní podklady</a><?php if($position==='finance_manager'):?> · <a href="accounting_ledger_admin.php">Peněžní pohyby</a><?php endif;?></p>
<?php if($error):?><div class="alert alert-danger" role="alert"><?=rewardH($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=rewardH($success)?></div><?php endif;?>
<?php if(!$ready):?><p>Evidence odměn ještě není připravena.</p><?php elseif(!$rules):?><div class="alert alert-warning">Chybí schválené sazby a účetní metodika. Odměny zůstávají zablokované do jejich doložení.</div><?php endif;?>
<?php if($ready&&$position==='sports_lead'):?><details class="card card-body mb-3"><summary>Uložit doložené pravidlo a sazbu</summary><form method="post"><?php rewardFields();?><input type="hidden" name="action" value="rule"><label class="d-block">Název rozhodnutí<input class="form-control" name="title" required maxlength="160"></label><label class="d-block">Druh<select class="form-select" name="kind"><option value="coach">Trenér</option><option value="athlete">Sportovec</option></select></label><label class="d-block">Jednotka<select class="form-select" name="unit"><option value="hour">Hodina (trenér)</option><option value="training">Uzavřený trénink</option></select></label><label class="d-block">Sazba v Kč<input class="form-control" name="rate" inputmode="decimal" required></label><div class="row"><label class="col">Platí od<input class="form-control" type="date" name="valid_from" required></label><label class="col">Platí do<input class="form-control" type="date" name="valid_to" required></label></div><label class="d-block">Schválené rozhodnutí / smluvní podklad<input class="form-control" name="approval_evidence" required maxlength="2000"></label><label class="d-block">Účetní metodika a schválený způsob předání<input class="form-control" name="accounting_method" required maxlength="2000"></label><?php rewardConfirm();?><button class="btn btn-primary">Uložit neměnné pravidlo</button></form></details><?php endif;?>
<?php if($ready&&$position!=='finance_manager'):?><details class="card card-body mb-4"><summary>Předložit nový výkaz nebo odměnu sportovce</summary><form method="post"><?php rewardSubmitForm($rules,$trainers,$people);?></form></details><?php endif;?>
<h2 class="h4">Nároky a jejich vypořádání</h2><?php foreach($claims as $c):$v=clubRewardVersion($pdo,(int)$c['current_version_id']);$s=json_decode($v['snapshot_json'],true,512,JSON_THROW_ON_ERROR);$paid=clubRewardPaid($pdo,(int)$c['id']);$approved=$c['approved_version_id']?clubRewardVersion($pdo,(int)$c['approved_version_id']):null;$balance=($approved?(int)$approved['amount_minor']:0)-$paid;$changed=clubRewardChanged($pdo,$c,$v);$dq=$pdo->prepare('SELECT * FROM club_reward_decisions WHERE version_id=?');$dq->execute([$v['id']]);$decision=$dq->fetch(PDO::FETCH_ASSOC);?>
<article class="card card-body mb-4"><h3 class="h5">#<?=(int)$c['id']?> · <?=$c['kind']==='coach'?'Trenér':'Sportovec'?> #<?=(int)$c['subject_id']?> · <?=rewardH($c['date_from'].' – '.$c['date_to'])?></h3><p>Verze <?=(int)$v['version']?> · <?=rewardH($decision?($decision['outcome']==='approved'?'Schváleno':'Vráceno k doplnění'):'Čeká na posouzení')?> · předloženo <?=rewardH(rewardMoney((int)$v['amount_minor']))?><br>Schváleno <?=rewardH(rewardMoney($approved?(int)$approved['amount_minor']:0))?> · skutečně vyplaceno <?=rewardH(rewardMoney($paid))?> · <strong><?=$balance<0?'K vrácení':'Zbývá doplatit'?> <?=rewardH(rewardMoney(abs($balance)))?></strong></p>
<?php if($changed):?><div class="alert alert-warning">Zdrojová činnost se změnila. Původní schválený podklad zůstává uložen; další výplata vyžaduje opravnou verzi a nové schválení.</div><?php endif;?>
<details><summary>Podklady a historie</summary><p><?=rewardH($s['rule']['title'].' · '.$s['rule']['approval_evidence'])?><br><?=rewardH($v['recipient_evidence'])?></p><table class="table"><thead><tr><th>Datum</th><th>Činnost</th><th>Minuty</th><th>Částka</th><th>Podklad</th></tr></thead><tbody><?php foreach($s['lines'] as $line):?><tr><td><?=rewardH($line['date'])?></td><td><?=rewardH($line['label'])?></td><td><?=(int)$line['minutes']?></td><td><?=rewardH(rewardMoney((int)$line['amount_minor']))?></td><td><?=rewardH(($line['source']==='dalsi_cinnosti'?'Další činnost #':'Uzavření tréninku #').$line['id'])?></td></tr><?php endforeach;?></tbody></table><?php $history=$pdo->prepare('SELECT v.*,d.outcome,d.reason AS decision_reason FROM club_reward_versions v LEFT JOIN club_reward_decisions d ON d.version_id=v.id WHERE v.claim_id=? ORDER BY v.version');$history->execute([$c['id']]);foreach($history->fetchAll(PDO::FETCH_ASSOC) as $old):?><p>Verze <?=(int)$old['version']?> · <?=rewardH(rewardMoney((int)$old['amount_minor']).' · '.$old['reason'].' · '.($old['decision_reason']??'Čeká na posouzení'))?></p><?php endforeach;?></details>
<?php if($position==='sports_lead'&&!$decision):?><form method="post" class="my-3"><?php rewardFields();?><input type="hidden" name="action" value="decide"><input type="hidden" name="version_id" value="<?=(int)$v['id']?>"><label>Rozhodnutí<select class="form-select" name="outcome"><option value="approved">Schválit doloženou verzi</option><option value="returned">Vrátit k doplnění</option></select></label><?php rewardConfirm();?><button class="btn btn-primary">Zaznamenat rozhodnutí</button></form><?php endif;?>
<?php if($position!=='finance_manager'):?><details class="my-3"><summary>Předložit opravnou verzi</summary><form method="post"><?php rewardSubmitForm($rules,$trainers,$people,$c,$v);?></form></details><?php endif;?>
<?php if($position==='finance_manager'&&$balance!==0):?><details class="my-3"><summary>Přiřadit skutečnou výplatu nebo vrácení přeplatku</summary><form method="post"><?php rewardFields();?><input type="hidden" name="action" value="pay"><input type="hidden" name="claim_id" value="<?=(int)$c['id']?>"><label class="d-block">Doložený pohyb<select class="form-select" name="movement_id" required><option value="">Vyberte peněžní pohyb</option><?php foreach($movements as $m):?><option value="<?=(int)$m['id']?>"><?=rewardH('#'.$m['id'].' '.$m['effective_on'].' '.$m['source_reference'].' '.rewardMoney((int)$m['amount_minor']))?></option><?php endforeach;?></select></label><label class="d-block">Částka v Kč<input class="form-control" name="amount" inputmode="decimal" required></label><label class="d-block">Skutečné datum pohybu<input class="form-control" type="date" name="paid_on" required></label><label class="d-block">Kdo převzal / vrátil peníze a doklad převzetí<input class="form-control" name="received_by" maxlength="2000" required></label><?php rewardConfirm();?><button class="btn btn-success">Přiřadit doložené vypořádání</button></form></details><?php endif;?></article><?php endforeach;?></main></body></html>
